import csv, math
vals=list(csv.DictReader(open(VALUES_CSV)))
cat=list(csv.DictReader(open(CATALOG_CSV)))
def tid(zone,cls):
    for r in cat:
        if r['point_uri'].endswith(f'#Zone_{zone}.{cls}'): return r['timeseries_id']
zones=['F1_Z01','F2_Z01','F2_Z02','F2_Z03','F2_Z04','F2_Z05','F2_Z06','F3_Z02','F3_Z03','F3_Z05','F4_Z01','F4_Z02','F4_Z03','F4_Z04']
T=tid('F3_Z01','Zone_Air_Temperature_Sensor')
d={r['timestamp']:float(r['value']) for r in vals if r['timeseries_id']==T}
ts=sorted(d); x=[d[t] for t in ts]; mx=sum(x)/len(x)
sx=math.sqrt(sum((a-mx)**2 for a in x)/len(x)); print('std F3_Z01', round(sx,3))
print('zone      corr with F3_Z01')
for z in zones:
    try: U=tid(z,'Zone_Air_Temperature_Sensor')
    except: continue
    e={r['timestamp']:float(r['value']) for r in vals if r['timeseries_id']==U}
    y=[e[t] for t in ts]; my=sum(y)/len(y)
    cov=sum((a-mx)*(b-my) for a,b in zip(x,y))/len(x)
    sy=math.sqrt(sum((b-my)**2 for b in y)/len(y))
    print(z, round(cov/(sx*sy),3))
